-- The 7 Alenjaz software cases as drafts (published = false).
-- Needs migration 0011_case_details.sql. Cases whose address already exists are skipped.

insert into cases (slug, title, client, area, status, platform, country, year, url, summary, situation, solution, metrics, features, stack, app_store_url, play_store_url, testimonial, cover_path, cover_alt, gallery, featured, published, sort) values
('auto-bazar-app', 'Auto Bazar — appen', 'Auto Bazar', 'plattformar', 'live', 'app', 'Syrien', 2026, null, 'Marknadsplatsens app för iPhone och Android, med chatt i realtid, bevakade sökningar och lokala betalsätt.', 'Marknadsplatsen behövde riktiga appar för iPhone och Android, med chatt, notiser och betalningar. Det på en marknad där de flesta internationella betaltjänster inte finns.', 'Vi byggde en app som finns i både App Store och Google Play. Köpare och säljare chattar i realtid, får en notis när något de bevakar dyker upp, och bokar och betalar med lokala betalsätt. I bakgrunden håller en automation varumärket aktivt i sociala medier varje dag.', '[{"value":"2","label":"appbutiker: App Store och Google Play"},{"value":"5","label":"kategorier"},{"value":"AR+EN","label":"helt tvåspråkig"},{"value":"24/7","label":"automatiska notiser och inlägg"}]'::jsonb, array['Chatt i realtid mellan köpare och säljare', 'Notiser för bevakade sökningar', 'Lokala betalsätt', 'Bokningar och premiumannonser', 'Inloggning med Apple och Google', 'Automatiska inlägg i sociala medier']::text[], array['Flutter']::text[], 'https://apps.apple.com/us/app/id6769161259', 'https://play.google.com/store/apps/details?id=com.elenjaz.haboub', null, '/images/cases/auto-bazar-app.jpg', 'Två mobiler med Auto Bazar-appen på arabiska: startsidan med kategorier och en lista med bilannonser', '[{"path":"/images/cases/autobazar-mobile.jpg","alt":"Appens startsida med sökfält, kategorier och utvalda annonser"}]'::jsonb, false, false, 100),
('auto-bazar-webb', 'Auto Bazar — marknadsplatsen', 'Auto Bazar', 'plattformar', 'live', 'web', 'Syrien', 2026, 'https://autobazarsyria.com', 'En tvåspråkig marknadsplats för bilar, delar, bostäder och uthyrning, byggd för svaga uppkopplingar och för att synas på Google.', 'Köpare och säljare i Syrien var utspridda i grupper på sociala medier, utan ett ställe att lita på för bilar, delar, bostäder och uthyrning. Auto Bazar behövde en snabb marknadsplats med arabiska först, som fungerar även på svag uppkoppling.', 'Vi designade och byggde en tvåspråkig marknadsplats där vem som helst kan lägga upp eller hitta en annons på några minuter. Den har smart sökning, ett steg-för-steg-flöde för att sälja och en översikt för säljare. Sajten installeras på telefonen som en app och byggdes för att ranka på Google från första dagen.', '[{"value":"5","label":"kategorier på en marknadsplats"},{"value":"14","label":"provinser i Syrien"},{"value":"AR+EN","label":"helt tvåspråkig"},{"value":"PWA","label":"installeras som en app"}]'::jsonb, array['Bilar, delar, bostäder och uthyrning på ett ställe', 'Sök på stad, märke och modell', 'En annons på några minuter, steg för steg', 'Översikt för säljare med bokningar och bevakningar', 'Notiser direkt, och fungerar utan uppkoppling', 'Byggd för att hittas på Google']::text[], array['Next.js', 'React', 'TypeScript']::text[], 'https://apps.apple.com/us/app/id6769161259', 'https://play.google.com/store/apps/details?id=com.elenjaz.haboub', null, '/images/cases/auto-bazar-web.jpg', 'Auto Bazars startsida i en webbläsare och i en mobil, med sökformulär för bilar, delar och bostäder', '[{"path":"/images/cases/autobazar-mobile.jpg","alt":"Marknadsplatsen i mobilen: sökfält, kategorier och utvalda annonser"}]'::jsonb, false, false, 110),
('ostazi', 'Ostazi', 'Ostazi', 'plattformar', 'live', 'web', 'Saudiarabien', 2026, 'https://ostazi-lovat.vercel.app', 'En plattform för privatlektioner som kopplar ihop elever i Saudiarabien med granskade lärare.', 'Föräldrar i Saudiarabien har svårt att hitta en lärare de kan lita på. Förmedlingen som skulle lösa det drevs med kalkylark, WhatsApp-trådar och betalningar som fördes för hand.', 'Vi byggde en plattform för föräldrar, lärare och förmedlingen. Föräldrar hittar och bokar en granskad lärare och betalar direkt. Lärare sköter sitt schema, och förmedlingen matchar och betalar ut från en och samma översikt. Lektionerna sker över video.', '[{"value":"3","label":"portaler i en produkt"},{"value":"8","label":"ämnen, bland annat Qudurat och Tahsili"},{"value":"AR","label":"arabiska först"}]'::jsonb, array['Lärarprofiler och bokning direkt', 'Lektionspaket som betalas i förväg', 'Lärarportal för schema och anteckningar', 'Föräldraportal med läxor och ombokning', 'Översikt för matchning och utbetalningar', 'Inloggning utan lösenord']::text[], array['Next.js', 'React']::text[], null, null, null, '/images/cases/ostazi-cover.jpg', 'Ostazis startsida på arabiska i en webbläsare och i en mobil, med sökning efter lärare på ämne och årskurs', '[{"path":"/images/cases/ostazi-mobile.jpg","alt":"Ostazi i mobilen: rubrik, knappar för att hitta en lärare och sökformulär"}]'::jsonb, false, false, 120),
('fastighetsplattform', 'Fastighetsplattform med eget CRM', 'Abu Shafiq Real Estate', 'interna-system', 'live', 'web', 'Syrien', 2026, null, 'En tvåspråkig fastighetssajt med sök och filter, och ett internt system där mäklarkontoret sköter annonser och köpare från telefonen.', 'Ett upptaget mäklarkontor hade sina objekt, köparnas önskemål och alla samtal på papper och i WhatsApp. Det fanns ingen sajt att visa objekten för nya kunder.', 'Vi byggde en fastighetssajt med bra sökning och ett internt system där kontoret lägger upp objekt och bilder, håller koll på vad varje köpare letar efter och svarar på förfrågningar. Allt går att sköta från telefonen.', '[{"value":"14","label":"provinser att söka i"},{"value":"11","label":"typer av fastigheter"},{"value":"PWA","label":"installeras som en app"}]'::jsonb, array['Sök på typ, område och pris', 'Bildgallerier med WhatsApp-knapp', 'Enkel hantering av annonser', 'Köparförfrågningar med knappar för samtal och WhatsApp', 'Installeras på telefonen som en app']::text[], array['Next.js', 'React']::text[], null, null, null, null, null, '[]'::jsonb, false, false, 130),
('hhm-kabelverlegung', 'HHM Kabelverlegung', 'HHM Kabelverlegung', 'webb', 'live', 'web', 'Tyskland', 2024, 'https://hhm-kabelverlegung.de', 'En tyskspråkig företagssajt för en kabel- och infrastrukturentreprenör, med en egen admin där ägaren uppdaterar allt själv.', 'En tysk entreprenör inom kabelförläggning behövde en trovärdig sajt för att vinna uppdrag från företag och kommuner, och ett sätt att uppdatera den utan att ringa en utvecklare.', 'Vi byggde en snabb företagssajt på tyska som gör besökare till förfrågningar. Till den hör en privat admin där ägaren kan ändra varje del av sajten utan hjälp.', '[{"value":"DE","label":"byggd för den tyska marknaden"},{"value":"100 %","label":"av innehållet redigerbart av ägaren"}]'::jsonb, array['Tydlig översikt över tjänsterna', 'Kontaktformulär direkt till inkorgen', 'Privat admin för att uppdatera sajten']::text[], array[]::text[], null, null, null, '/images/cases/hhm-kabelverlegung.jpg', 'HHM Kabelverlegungs tyska startsida i en webbläsare och i en mobil, med knappen Kontakt uns', '[]'::jsonb, false, false, 140),
('walla-matchning', 'Walla Matchning', 'Walla Matchning AB', 'webb', 'live', 'web', 'Sverige', 2026, 'https://www.wallajobb.se', 'Ett eget WordPress-tema för en bemannings- och rekryteringsbyrå i Halmstad, som teamet redigerar själva utan sidbyggare.', 'Byrån hade en gammal och långsam sajt som var svår att redigera och som inte talade tydligt till vare sig arbetssökande eller arbetsgivare.', 'Vi byggde en snabb WordPress-sajt i byråns egen identitet, med tydliga vägar för arbetssökande och för arbetsgivare. Teamet kan ändra allt själva, utan utvecklare.', '[{"value":"8","label":"sidor klara från första dagen"},{"value":"0","label":"utvecklare behövs för ändringar"}]'::jsonb, array['Egna vägar för arbetssökande och arbetsgivare', 'CV- och kontaktformulär direkt till inkorgen', 'Allt redigerbart av teamet', 'Snabb, lätt och enkel att underhålla']::text[], array['WordPress']::text[], null, null, null, '/images/cases/wallajobb.jpg', 'Walla Matchnings startsida i en webbläsare, med rubriken Rätt person på rätt plats och knappar för jobbsökare och arbetsgivare', '[]'::jsonb, false, false, 150),
('mawqef', 'Mawqef — digital parkering', 'Mawqef', 'plattformar', 'dev', 'both', 'Syrien', 2026, null, 'En plattform för gatuparkering i Syrien: förare betalar med en QR-kod, kontrollanter kollar bilar på sekunder och kommunen ser intäkterna på en karta.', 'Gatuparkering i syriska städer sköts med kontanter, papperslappar och gissningar. Kommunen har ingen överblick och förarna ingen bekvämlighet.', 'En hel plattform för digital parkering. Förare skannar en QR-kod och betalar från sin plånbok i appen, kontrollanter kollar en bil på några sekunder, och kommunen sköter zoner, priser och intäkter live på en karta.', '[{"value":"3","label":"appar, en plattform"},{"value":"QR","label":"skanna och betala"},{"value":"Live","label":"intäkter på en karta"}]'::jsonb, array['Förarapp med QR-parkering och digital plånbok', 'Kontrollantapp som kollar registreringsnummer på sekunder', 'Översikt för kommunen med zoner på en karta', 'Utskrivbara zonskyltar med QR-koder', 'Lokala sätt att fylla på och värdekort']::text[], array['Flutter', 'Next.js']::text[], null, null, null, null, null, '[]'::jsonb, false, false, 160)
on conflict (slug) do nothing;

-- Already imported without photos? This adds the screenshots, but only where no cover has been set yet.
update cases set cover_path = '/images/cases/auto-bazar-app.jpg', cover_alt = 'Två mobiler med Auto Bazar-appen på arabiska: startsidan med kategorier och en lista med bilannonser', gallery = case when gallery = '[]'::jsonb then '[{"path":"/images/cases/autobazar-mobile.jpg","alt":"Appens startsida med sökfält, kategorier och utvalda annonser"}]'::jsonb else gallery end where slug = 'auto-bazar-app' and cover_path is null;
update cases set cover_path = '/images/cases/auto-bazar-web.jpg', cover_alt = 'Auto Bazars startsida i en webbläsare och i en mobil, med sökformulär för bilar, delar och bostäder', gallery = case when gallery = '[]'::jsonb then '[{"path":"/images/cases/autobazar-mobile.jpg","alt":"Marknadsplatsen i mobilen: sökfält, kategorier och utvalda annonser"}]'::jsonb else gallery end where slug = 'auto-bazar-webb' and cover_path is null;
update cases set cover_path = '/images/cases/ostazi-cover.jpg', cover_alt = 'Ostazis startsida på arabiska i en webbläsare och i en mobil, med sökning efter lärare på ämne och årskurs', gallery = case when gallery = '[]'::jsonb then '[{"path":"/images/cases/ostazi-mobile.jpg","alt":"Ostazi i mobilen: rubrik, knappar för att hitta en lärare och sökformulär"}]'::jsonb else gallery end where slug = 'ostazi' and cover_path is null;
update cases set cover_path = '/images/cases/hhm-kabelverlegung.jpg', cover_alt = 'HHM Kabelverlegungs tyska startsida i en webbläsare och i en mobil, med knappen Kontakt uns', gallery = case when gallery = '[]'::jsonb then '[]'::jsonb else gallery end where slug = 'hhm-kabelverlegung' and cover_path is null;
update cases set cover_path = '/images/cases/wallajobb.jpg', cover_alt = 'Walla Matchnings startsida i en webbläsare, med rubriken Rätt person på rätt plats och knappar för jobbsökare och arbetsgivare', gallery = case when gallery = '[]'::jsonb then '[]'::jsonb else gallery end where slug = 'walla-matchning' and cover_path is null;

select slug, title, published, status, cover_path from cases order by sort;
